inputs.script:
// Get email input from Portal Users
let { Email } = input.config();

// Extract domain from email
if (!Email || !Email.includes('@')) {
    output.set('matchStatus', '❌ Invalid email');
    output.set('matchedWebsite', null);
    output.set('matchedEmail', null);
    return;
}

let domain = Email.split('@')[1].toLowerCase();

// Get records from Onboarding table
let onboardingTable = base.getTable("Onboarding");
let onboardingRecords = await onboardingTable.selectRecordsAsync({
    fields: ["Website Link", "Email Address"]
});

// Initialize result variables
let found = false;
let matchedWebsite = null;
let matchedEmail = null;

for (let record of onboardingRecords.records) {
    let website = record.getCellValueAsString("Website Link")?.toLowerCase() || "";
    let onboardingEmail = record.getCellValueAsString("Email Address")?.toLowerCase() || "";

    // Clean website domain (remove http, https, www)
    let websiteDomain = website
        .replace(/^https?:\/\//, '')
        .replace(/^www\./, '')
        .split('/')[0]
        .trim();

    // Extract domain from onboarding email (if exists)
    let emailDomain = onboardingEmail.includes('@') ? onboardingEmail.split('@')[1].trim() : "";

    // Match either domain
    if (domain === websiteDomain || domain === emailDomain) {
        found = true;
        matchedWebsite = website;
        matchedEmail = onboardingEmail;
        break;
    }
}

// Return results
if (found) {
    output.set('matchStatus', ' found');
    output.set('matchedWebsite', matchedWebsite);
    output.set('matchedEmail', matchedEmail);
} else {
    output.set('matchStatus', ' not found');
    output.set('matchedWebsite', null);
    output.set('matchedEmail', null);
}

// 🔹 Input: Company name to search for (from Onboarding record)
let { companyName } = input.config();

// Use only the first name if an array is passed
let inputCompany = (companyName[0] || "").trim().toLowerCase();

if (!inputCompany) {
    output.set("status", "❌ No company name provided");
    output.set("workspaceRecordID", null);
    output.set("workspaceName", null);
    return;
}

// 🔹 Reference Workspace IDs table
let workspaceTable = base.getTable("Workspace IDs");
let records = await workspaceTable.selectRecordsAsync({ fields: ["Name"] });

// 🔍 Try to find a matching company name
let match = records.records.find(record => {
    let name = record.getCellValueAsString("Name");
    return name.trim().toLowerCase() === inputCompany;
});

if (match) {
    output.set("status", " Match found");
    output.set("workspaceRecordID", match.id);
    output.set("workspaceName", match.getCellValueAsString("Name"));
} else {
    output.set("status", " No match");
    output.set("workspaceRecordID", null);
    output.set("workspaceName", null);
}
